#include <GlassHelix/artifacts/nf1_replay.hh>
#include <cassert>
#include <fstream>
#include <iostream>
using namespace glasshelix::artifacts;
int main(int argc,char**argv){const std::string path=argc>1?argv[1]:"nf1-replay.artifact";nf1_replay_record r{};r.status=nf1_run_status::succeeded_output;r.logical_inputs={.25f,.5f,.1f,.2f};r.logical_output={.3f};r.registered_blocks={"local-add#10@1"};r.numerical_policy="f32-rne-propagate";r.glasshelix_source="0000000000000000000000000000000000000001";r.cellerator_source="0000000000000000000000000000000000000002";std::string error;assert(write_nf1_replay(path,r,&error));nf1_replay_record loaded{};assert(read_nf1_replay(path,&loaded,&error));std::vector<float> result;assert(replay_defined_operation(loaded,&result,&error)&&result[0]==.3f);loaded.logical_inputs[2]=.4f;assert(replay_defined_operation(loaded,&result,&error)&&result[0]==.6f);loaded.status=nf1_run_status::pending;assert(!replay_defined_operation(loaded,&result,&error));loaded.status=nf1_run_status::failed;loaded.failure="native-failure";assert(!replay_defined_operation(loaded,&result,&error));{std::ofstream bad(path,std::ios::trunc);bad<<"broken\n";}assert(!read_nf1_replay(path,&loaded,&error));{std::ofstream old(path,std::ios::trunc);old<<"GH_NF1_REPLAY|99|pending|f32-rne-propagate|0000000000000000000000000000000000000001|0000000000000000000000000000000000000002||||\n";}assert(!read_nf1_replay(path,&loaded,&error));std::cout<<"artifact tests passed\n";}
